sys_script_client.script:
function onSubmit() {
	var task1 = g_form.getValue('u_needit_task1');
	var task2 = g_form.getValue('u_needit_task2');
	var task3 = g_form.getValue('u_needit_task3');

	var count = 0;
	var arrTask = [task1, task2, task3];

	for (i = 0; i < arrTask.length; i++) {
		if(arrTask[i] == 'true') {
			count++;
		}
	}

	if (count < 2) {
		g_form.addErrorMessage ("A minimum of 2 NeedIt Task must be selected.");
		return false;
		//current.setAbortAction(true); //The object "current" should not be used in client scripts.
	}

}
